for (const module of COURSE) {
  module.qa = module.concepts.map((concept, index) => ({ topic: concept[0], items: TOPIC_QA[module.id]?.[index] || [] }));
  if (SELF_QA[module.id]) module.qa.push({ topic: 'Self-learning & real-world application', items: SELF_QA[module.id] });
}
